from pathlib import Path
import re,html
root=Path(__file__).resolve().parents[1]/'dist'
s=(root/'work/index.html').read_text()
cards=[]
for match in re.finditer(r'<a\b[^>]*class="[^"]*portfolio-project-card[^\"]*"[^>]*>.*?</a>',s,re.S):
 a=match.group();href=re.search(r'href="([^"]+)"',a).group(1)
 title=html.unescape(re.sub('<[^>]*>','',re.search(r'<h4[^>]*>(.*?)</h4>',a,re.S).group(1)))
 image=re.search(r'<img[^>]*src="([^"]+)"',a).group(1)
 ps=[html.unescape(re.sub('<[^>]*>','',x)) for x in re.findall(r'<p[^>]*>(.*?)</p>',a,re.S)]
 cards.append((href,title,image,ps[-1] if ps else ''))
assert len(cards)==13,len(cards)
roles={'Horal':'Product Designer','Radius / Pay4Me':'Product Designer','Bizinc':'UI/UX Intern → UI/UX Manager','Vista Digital Banking':'Product Designer'}
projectMarkup=''.join(f'<article class="simple-project"><a href="{u}" aria-label="Read {html.escape(t)} case study"><div class="simple-project-image"><img src="{im}" alt="{html.escape(t)} project preview" loading="lazy" width="1240" height="860"></div><div class="simple-project-copy"><p class="simple-project-role">{html.escape(roles.get(t,"Product design case study"))}</p><h3>{html.escape(t)} <span aria-hidden="true">↗</span></h3><p>{html.escape(desc)}</p><span class="simple-project-action">Read case study</span></div></a></article>' for u,t,im,desc in cards)
